#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);

    int s = 0;
    for (int i = 0; i < n; i++) {
        int num;
        scanf("%d", &num);

        if (i % 2 == 0) {
            s = s + num;
        }
    }

    printf("%d\n", s);
    return 0;
}

